h=sha(r/'kernel.wasm');(r/'registry.mjs').write_text('// Generated by stream-attention/build.py\nexport const STREAM_WASM_SHA256='+json.dumps(h)+';\n')
record={'hikeCommit':p['hikeCommit'],'compilerSha256':sha(t/'hikec'),'backend':'wabt','mode':'normal','sourceSha256':sha(r/'kernel.hike'),'wasmSha256':h,'watSha256':sha(r/'kernel.wat'),'runtimeSha256':sha(runtime),'imports':[],'abi':abi,'command':command,'versions':p['versions']};(r/'build-record.json').write_text(json.dumps(record,indent=2)+'\n');print(json.dumps({'wasmSha256':h,'bytes':(r/'kernel.wasm').stat().st_size}))
